def reverse_middle(lst):
    n = len(lst)
    if n < 4:
        raise ValueError("List must contain at least four elements")
    start = n // 2 - 1
    end = n // 2 + 1
    if n % 2 == 0:
        return lst[start:end][::-1]
    else:
        return [lst[start], lst[(n // 2)], lst[end]][::-1]
```

